import axios from 'axios';
import { setupEncryptInterceptors } from '../src/index';

const service = axios.create({
  baseURL: 'http://localhost:8080/api',
  timeout: 50000,
});

setupEncryptInterceptors(service, {
  enabled: true,
  publicKey: 'MFwwDQYJKoZIhvcNAQEBBQADSwAwSAJBAKoR8mX0rGKLqzcWmOzbfj64K8ZIgOdHnzkXSOVOZbFu/TJhZ7rFAN+eaGkl3C4buccQd/EjEsj9ir7ijT7h96MCAwEAAQ==',
  privateKey: '',
});

async function testEncrypt() {
  try {
    const response = await service.post('/test/encrypt', {
      username: 'admin',
      password: '123456',
    }, {
      headers: { isEncrypt: 'true' },
    });

    console.log('响应数据:', response.data);
  } catch (error) {
    console.error('请求失败:', error);
  }
}

testEncrypt();
